import numpy as np
from scipy.optimize import least_squares
t=df['t'].values; P=df['P'].values; y=df['dP_dt'].values
V=np.var(y)
def model(p):
    a,b,c,d,e,f,g,q,h,k=p
    return -a*t**b*(1-np.exp(-c*P)) - d*P - e*P**2 - f*t*P - g*t**q*P*np.exp(-h*P) - k*np.sqrt(t)*np.exp(-P)
best=None
for x0 in [[2.4,0.55,2,0.2,0.2,0.03,0.3,0.5,0.5,0.5],[2.4,0.55,7,0.1,0.26,-0.03,0.3,1,1,0.5],[2.5,0.5,3,0.2,0.3,0.0,0.5,1,0.5,1.0]]:
    try:
        r=least_squares(lambda p: model(p)-y, x0, max_nfev=5000)
        if best is None or r.cost<best.cost: best=r
    except Exception as ex: print(ex)
res=best.fun
print('NMSE',np.mean(res**2)/V, np.round(best.x,4))
